def flatten_list(nested_list: list) -> list:
    if not isinstance(nested_list, list):
        raise TypeError("Input must be a list")

    result = []
    def flatten(current_list):
        for item in current_list:
            if isinstance(item, list):
                flatten(item)
            else:
                result.append(item)
    flatten(nested_list)
    return result

