def balancedParenthesesAndSum(expression):
    # Check if the expression is balanced
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return -1
            stack.pop()
    # Check if the stack is empty
    if len(stack) != 0:
        return -1
    # Calculate the sum of digits
    sum_digits = 0
    for char in expression:
        if char.isdigit():
            sum_digits += int(char)
    return sum_digits

