{"code": "import heapq

def dijkstra_optimized(graph: List[List[Tuple[int, int]]], src: int) -> List[int]:
    if not graph:
        return []

    V = len(graph)
    dist = [float('inf')] * V
    dist[src] = 0
    priority_queue = [(0, src)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            if dist[neighbor] > dist[current_node] + weight:
                dist[neighbor] = dist[current_node] + weight
                heapq.heappush(priority_queue, (dist[neighbor], neighbor))

    return dist"}

