    for j in range(5):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(5):
            for k in range(j + 1):
                dp[i][j] += dp[i - 1][k]

    # Sum all the valid strings of length n
    return sum(dp[n])

