def min_sessions(tasks, sessionTime):
    sessions = 0
    current_sum = 0
    for task in tasks:
        if current_sum + task <= sessionTime:
            current_sum += task
        else:
            sessions += 1
            current_sum = task
    if current_sum > 0:
        sessions += 1
    return sessions

